const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // Define Shanghai region
  var shanghai = ee.Geometry.Polygon([
    [[120.85, 30.67], [121.97, 30.67], [121.97, 31.53], [120.85, 31.53], [120.85, 30.67]]
  ]);

  // Define time periods
  var period1_start = '2020-02-10';
  var period1_end = '2020-02-25';
  var period2_start = '2020-04-20';
  var period2_end = '2020-05-12';

  // Get NO2 collections
  var no2_col1 = ee.ImageCollection('COPERNICUS/S5P/OFFL/L3_NO2')
    .filterDate(period1_start, period1_end)
    .filterBounds(shanghai)
    .select('tropospheric_NO2_column_number_density');

  var no2_col2 = ee.ImageCollection('COPERNICUS/S5P/OFFL/L3_NO2')
    .filterDate(period2_start, period2_end)
    .filterBounds(shanghai)
    .select('tropospheric_NO2_column_number_density');

  // Check collection sizes
  var size1 = no2_col1.size().getInfo();
  var size2 = no2_col2.size().getInfo();

  console.log(`Period 1 (Feb) Images: ${size1}`);
  console.log(`Period 2 (Apr-May) Images: ${size2}`);

  if (size1 === 0 || size2 === 0) {
    console.log("<answer>C1</answer>");
    return;
  }

  // Create mean composites
  var mean1 = no2_col1.mean();
  var mean2 = no2_col2.mean();

  // Calculate mean NO2 values
  var result1 = mean1.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: shanghai,
    scale: 1000,
    maxPixels: 1e9
  }).get('tropospheric_NO2_column_number_density');

  var result2 = mean2.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: shanghai,
    scale: 1000,
    maxPixels: 1e9
  }).get('tropospheric_NO2_column_number_density');

  // Check pixel counts
  var count1 = mean1.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: shanghai,
    scale: 1000,
    maxPixels: 1e9
  }).get('tropospheric_NO2_column_number_density');

  var count2 = mean2.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: shanghai,
    scale: 1000,
    maxPixels: 1e9
  }).get('tropospheric_NO2_column_number_density');

  var val1 = result1.getInfo();
  var val2 = result2.getInfo();
  var pix1 = count1.getInfo();
  var pix2 = count2.getInfo();

  console.log(`Period 1 NO2: ${val1 ? val1.toFixed(6) : 'null'}, Pixels: ${pix1}`);
  console.log(`Period 2 NO2: ${val2 ? val2.toFixed(6) : 'null'}, Pixels: ${pix2}`);

  // Validation checks
  if (pix1 === 0 || pix2 === 0) {
    console.log("<answer>C2</answer>");
    return;
  }

  if (val1 === null || val2 === null || isNaN(val1) || isNaN(val2)) {
    console.log("<answer>C3</answer>");
    return;
  }

  // Check for valid range (NO2 should be positive and reasonable)
  if (val1 < 0 || val2 < 0 || val1 > 1e-3 || val2 > 1e-3) {
    console.log("<answer>C3</answer>");
    return;
  }

  // Determine if there was an increase
  if (val2 > val1) {
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
